package gfx

// Font is an anti-aliased bitmap font: 4 bits of coverage per pixel, so text
// edges use the panel's gray levels. Fonts are generated by cmd/fontgen and
// live in package fonts; the data is a string so that it stays in flash.
//
// Data layout (little endian):
//
//	header  12 bytes: version, 0, count u16, ascent u16, descent u16,
//	        lineHeight u16, nominal ascent u16
//	glyphs  count x 12 bytes, sorted by rune: rune u16, bitmap offset u24,
//	        width u8, height u8, x offset i8, top u8 (from the top of the
//	        line box), advance u16 (1/16 px), 0
//	bitmaps 4 bits per pixel, high nibble first, rows padded to bytes
type Font struct {
	data    string
	count   int
	ascent  int
	descent int
	line    int
	bitmaps int // offset of the bitmap data
}

// NewFont wraps font data generated by cmd/fontgen.
func NewFont(data string) *Font {
	u16 := func(i int) int { return int(data[i]) | int(data[i+1])<<8 }
	f := &Font{
		data:    data,
		count:   u16(2),
		ascent:  u16(4),
		descent: u16(6),
		line:    u16(8),
	}
	f.bitmaps = 12 + 12*f.count
	return f
}

// Ascent is the height above the baseline of the tallest glyph.
func (f *Font) Ascent() int { return f.ascent }

// Descent is the depth below the baseline of the deepest glyph.
func (f *Font) Descent() int { return f.descent }

// LineHeight is the recommended distance between baselines.
func (f *Font) LineHeight() int { return f.line }

type glyph struct {
	off       int
	w, h      int
	xoff, top int
	adv       int // 1/16 px
}

// find returns the index of the glyph record for r, or -1.
func (f *Font) find(r rune) int {
	d := f.data
	key := func(i int) rune { o := 12 + 12*i; return rune(d[o]) | rune(d[o+1])<<8 }
	// ASCII fast path: the generated fonts start at ' ' without gaps.
	if i := int(r) - 32; i >= 0 && i < f.count && key(i) == r {
		return i
	}
	lo, hi := 0, f.count
	for lo < hi {
		m := (lo + hi) / 2
		if key(m) < r {
			lo = m + 1
		} else {
			hi = m
		}
	}
	if lo < f.count && key(lo) == r {
		return lo
	}
	return -1
}

func (f *Font) glyph(r rune) (g glyph, ok bool) {
	i := f.find(r)
	if i < 0 {
		if i = f.find('?'); i < 0 {
			return g, false
		}
	}
	d := f.data[12+12*i:]
	g.off = f.bitmaps + (int(d[2]) | int(d[3])<<8 | int(d[4])<<16)
	g.w, g.h = int(d[5]), int(d[6])
	g.xoff = int(int8(d[7]))
	g.top = int(d[8])
	g.adv = int(d[9]) | int(d[10])<<8
	return g, true
}

// Has reports whether the font has a glyph for r.
func (f *Font) Has(r rune) bool { return f.find(r) >= 0 }

// Width returns the advance width of s in pixels.
func (f *Font) Width(s string) int {
	pen := 0
	for _, r := range s {
		if g, ok := f.glyph(r); ok {
			pen += g.adv
		}
	}
	return (pen + 8) >> 4
}

// DrawText draws s with the left end of its baseline at (x, y) and returns
// the x coordinate after the last glyph. Coverage is blended with what is
// already in the frame buffer, so text can go on any background.
func DrawText(c Canvas, f *Font, x, y int, s string, level uint8) int {
	pen := x << 4
	top := y - f.ascent
	for _, r := range s {
		g, ok := f.glyph(r)
		if !ok {
			continue
		}
		f.draw(c, g, (pen+8)>>4+g.xoff, top+g.top, level)
		pen += g.adv
	}
	return (pen + 8) >> 4
}

// DrawTextCentered draws s horizontally centered on cx, baseline at y.
func DrawTextCentered(c Canvas, f *Font, cx, y int, s string, level uint8) {
	DrawText(c, f, cx-f.Width(s)/2, y, s, level)
}

// DrawTextRight draws s ending at x, baseline at y.
func DrawTextRight(c Canvas, f *Font, x, y int, s string, level uint8) {
	DrawText(c, f, x-f.Width(s), y, s, level)
}

func (f *Font) draw(c Canvas, g glyph, x0, y0 int, level uint8) {
	stride := (g.w + 1) / 2
	cw, ch := c.Size()
	for y := 0; y < g.h; y++ {
		py := y0 + y
		if py < 0 || py >= int(ch) {
			continue
		}
		row := g.off + y*stride
		for x := 0; x < g.w; x++ {
			px := x0 + x
			if px < 0 || px >= int(cw) {
				continue
			}
			a := f.data[row+x/2]
			if x&1 == 0 {
				a >>= 4
			}
			Blend(c, px, py, level, a&15)
		}
	}
}

// Wrap breaks s into lines no wider than width pixels, at spaces where
// possible. Newlines in s start new lines; an empty line is kept as "".
func Wrap(f *Font, s string, width int) []string {
	var lines []string
	for len(s) > 0 {
		para := s
		if i := indexByte(s, '\n'); i >= 0 {
			para, s = s[:i], s[i+1:]
		} else {
			s = ""
		}
		if para == "" {
			lines = append(lines, "")
			continue
		}
		for para != "" {
			n := fit(f, para, width)
			lines = append(lines, trimRight(para[:n]))
			para = trimLeft(para[n:])
		}
	}
	return lines
}

// fit returns how many bytes of s fit in width, breaking after a space if
// possible (always at least one rune).
func fit(f *Font, s string, width int) int {
	pen, lastSpace := 0, -1
	for i, r := range s {
		g, ok := f.glyph(r)
		if ok {
			pen += g.adv
		}
		if (pen+8)>>4 > width && i > 0 {
			if lastSpace > 0 {
				return lastSpace
			}
			return i
		}
		if r == ' ' {
			lastSpace = i + 1
		}
	}
	return len(s)
}

func indexByte(s string, b byte) int {
	for i := 0; i < len(s); i++ {
		if s[i] == b {
			return i
		}
	}
	return -1
}

func trimLeft(s string) string {
	for len(s) > 0 && s[0] == ' ' {
		s = s[1:]
	}
	return s
}

func trimRight(s string) string {
	for len(s) > 0 && s[len(s)-1] == ' ' {
		s = s[:len(s)-1]
	}
	return s
}
